import{z as t,x as s,o as B,c as d,q as r,j as l,D as A,d as e,s as n,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"资本流动的驱动","description":"","frontmatter":{"title":"资本流动的驱动","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/if-capital-flow-drivers.md","filePath":"econ/if-capital-flow-drivers.md","lastUpdated":1791063341000}'),p={name:"econ/if-capital-flow-drivers.md"};function C(c,E,D,f,m,h){const o=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=r('<h1 id="资本流动的驱动" tabindex="-1">资本流动的驱动 <a class="header-anchor" href="#资本流动的驱动" aria-label="Permalink to &quot;资本流动的驱动&quot;">​</a></h1><div class="epigraph"><p>资本流动不是储蓄缺口的快递，是风险偏好与资产负债表的共振：推力决定总量何时涨落，拉力决定谁先被冲垮。</p><footer>—— 据 Calvo 1998；Forbes and Warnock, JIE 2012；Rey 2013 整理</footer></div><p><a href="/econ/if-crossborder-dollar-cycle">上一课</a>把离岸美元信贷的进退写在银行账本上：美元汇率经估值渠道驱动全球杠杆。本课把银行、债券、股票与 FDI 放进同一张图，问总量：资本流动究竟被谁驱动——全球推力还是国内拉力，以及为什么同一阵风吹过，有的国家没事、有的国家断流。主干<a href="/econ/sudden-stop">突然停止</a>给了断流的形态，<a href="/econ/global-financial-cycle">全球金融周期</a>给了全球因子；本课的缺口是把「谁在驱动」写成可估计的分解，把脆弱性写成拉力侧的清单。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>直觉版本把资本流动写成储蓄与投资：穷国缺资本，富国多储蓄，钱往回报高处流。事实三层都不配合。其一，总额与净额完全不成比例：金融决策在总额上做，跨境总流动是经常账户差额的数倍到十倍量级——只看净额，丢掉绝大部分信息。其二，资本并不往低资本处流：<a href="/econ/lucas-paradox">卢卡斯悖论</a>在，<a href="/econ/feldstein-horioka">费尔德斯坦–堀冈</a>的储蓄投资相关也说明资本流动性远低于教科书。其三，流动极端地成批出现：涌入与骤停以「波」的形式横扫多个国家，共动远超各自基本面能解释的范围。缺口是把这三件事接进一个驱动分解。</p><p><span class="marginnote">危机前主要经济体的跨境总流动可达 GDP 的两成上下，而经常账户差额只有两三个百分点：用净额读全球金融，九成以上的信息被丢掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分解分四步。第一步把对象定成<strong>总额</strong>：银行信贷、债券、股票分别计，FDI 单列——它们对推力的敏感度不同。第二步分类极端事件：Forbes–Warnock 把资本流动的极端段落切成涌入、骤停、外逃、回撤四类，全球因子对骤停与外逃的解释力最强，本国产出新闻最弱。</p><p><span class="marginnote">四个名字其实是两双眼睛：涌入与骤停盯的是外国人（狂买本国资产 / 停止买入甚至撤退），外逃与回撤盯的是本国人（把钱搬出去 / 把在外面搬回来）。读到新闻里的「资本外逃」，先分清是外资撤退还是内资出逃——驱动因素与对策完全不同。</span>第三步摆变量：推力侧是 VIX、美国利率路径、美元与全球中介杠杆（上一课的机器）；拉力侧是制度、储备、外债的币种与期限、外部余额与增长。第四步做识别：全球因子是公共冲击，时间序列识别不了推拉，截面识别靠<strong>暴露差异</strong>——同样一阵风，美元债务多、储备薄的倒得快；推拉交互项才是要估的系数。</p>',9)),(B(),l(i,null,{default:A(()=>[n(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUSH%5B%22%E5%85%A8%E7%90%83%E6%8E%A8%E5%8A%9B%3A%20VIX%E3%80%81%E7%BE%8E%E5%9B%BD%E5%88%A9%E7%8E%87%E3%80%81%E7%BE%8E%E5%85%83%22%5D%20--%3E%20LEV%5B%22%E4%B8%AD%E4%BB%8B%E6%9D%A0%E6%9D%86%E4%B8%8E%E9%A3%8E%E9%99%A9%E5%81%8F%E5%A5%BD%22%5D%0A%20%20LEV%20--%3E%20GROSS%5B%22%E8%B7%A8%E5%A2%83%E6%80%BB%E6%B5%81%E5%8A%A8%22%5D%0A%20%20GROSS%20--%3E%20BS%5B%22%E5%9B%BD%E5%86%85%E8%B5%84%E4%BA%A7%E8%B4%9F%E5%80%BA%E8%A1%A8%3A%20%E5%A4%96%E5%80%BA%E5%B8%81%E7%A7%8D%E4%B8%8E%E6%9C%9F%E9%99%90%22%5D%0A%20%20BS%20--%3E%7C%22%E7%BC%93%E5%86%B2%E4%B8%8D%E8%B6%B3%22%7C%20STOP%5B%22%E9%AA%A4%E5%81%9C%E4%B8%8E%E8%B4%A7%E5%B8%81%E6%80%A5%E8%B4%AC%22%5D%0A%20%20BS%20--%3E%7C%22%E7%BC%93%E5%86%B2%E5%85%85%E8%B6%B3%22%7C%20ABS%5B%22%E5%90%B8%E6%94%B6%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20STOP%20--%3E%20CFM%5B%22%E7%AC%AC%E4%BA%8C%E5%B7%A5%E5%85%B7%3A%20%E5%B9%B2%E9%A2%84%E4%B8%8E%E7%AE%A1%E5%88%B6%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("机制是上一课估值渠道的放大版。推力松时，中介杠杆抬升，总额涌入，借款人的净值、抵押品与本币汇率一起走强——拉力侧的脆弱被繁荣盖住。推力紧时，边际借款人失联，Calvo 1998 的骤停开始：不是渐进减速而是状态切换，流量断裂经"),a("a",{href:"/econ/original-sin"},"原罪"),e("式的币种错配放大成汇率贬值、净值塌缩与产出收缩的第二轮。两难随之而来：Rey 2013 的结论是资本开放下浮动汇率不能买回货币自主，政策需要第二工具——本课程最后两课的外汇干预与资本管制就是那两个名字。不这么做会错在哪：把骤停全归咎国内治理（推力是公共的，事后问责选错了被告）；把总额流动当实物流动配置（它主要是资产负债表易手）；用经常账户判脆弱性（脆弱性在外债的币种与期限里）。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"币种错配的威力可以代个数：一家企业借了 1 亿美元外债，本币汇率从 10 贬到 15，这笔债按本币计就从 10 亿涨到 15 亿——债务凭空涨了五成，而企业一分钱没多花。贬值本身就是加杠杆，这就是骤停为什么总跟着产出危机。")],-1)),(B(),l(i,null,{default:A(()=>[n(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20TIGHT%5B%22%E6%8E%A8%E5%8A%9B%E6%94%B6%E7%B4%A7%3A%20%E9%A3%8E%E9%99%A9%E5%81%8F%E5%A5%BD%E9%80%86%E8%BD%AC%22%5D%20--%3E%20GONE%5B%22%E8%BE%B9%E9%99%85%E5%80%9F%E6%AC%BE%E4%BA%BA%E5%A4%B1%E8%81%94%22%5D%0A%20%20GONE%20--%3E%20BREAK%5B%22%E6%B5%81%E5%85%A5%E6%B5%81%E9%87%8F%E6%96%AD%E8%A3%82%22%5D%0A%20%20BREAK%20--%3E%20MISMATCH%5B%22%E5%B8%81%E7%A7%8D%E9%94%99%E9%85%8D%E6%9A%B4%E9%9C%B2%3A%20%E5%A4%96%E5%80%BA%E4%BB%A5%E5%A4%96%E5%B8%81%E8%AE%A1%22%5D%0A%20%20MISMATCH%20--%3E%20DEVAL%5B%22%E6%9C%AC%E5%B8%81%E6%80%A5%E8%B4%AC%22%5D%0A%20%20DEVAL%20--%3E%20NETWORTH%5B%22%E6%9C%AC%E5%B8%81%E8%AE%A1%E5%80%BA%E5%8A%A1%E4%B8%8E%E5%87%80%E5%80%BC%E6%81%B6%E5%8C%96%22%5D%0A%20%20NETWORTH%20--%3E%20COLLAT%5B%22%E6%8A%B5%E6%8A%BC%E5%93%81%E4%BB%B7%E5%80%BC%E4%B8%8B%E9%99%8D%22%5D%0A%20%20COLLAT%20--%3E%7C%22%E7%AC%AC%E4%BA%8C%E8%BD%AE%3A%20%E6%9B%B4%E6%B2%A1%E4%BA%BA%E5%80%9F%E5%87%BA%22%7C%20GONE%0A%20%20COLLAT%20--%3E%20SLOW%5B%22%E4%BA%A7%E5%87%BA%E6%94%B6%E7%BC%A9%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>推拉不是二选一：交互项才是结构，单独挑边都会把样本拟合成故事。不是所有流动都走价格敏感渠道：FDI 粘、汇款稳，骤停主要发生在可撤回的组合与银行渠道；纯国内的政治冲击也能触发断流，全球因子解释不完。测量有盲区：衍生品与贸易信贷低估流量，离岸发行把债记给谁常说不清。读完本课应当能做的判断是：先问一阵风有多硬（推力），再问船上压舱石有多少（拉力），两问分开，政策才对得上号。</p><p><span class="marginnote">初学者容易以为「拉力弱 = 流动少」，实际上拉力主要不是决定风多大，而是决定风来了船翻不翻：拉力侧的储备、制度、债务期限是压舱石，不改变全球风的强度，只决定同一阵风下谁先断流。这也是为什么脆弱性清单比流量预测更有政策价值。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>资本流动要读总额：总流动数倍于经常账户，净额丢掉九成信息。</li><li>极端流动成批出现：骤停与外逃由全球推力主导，本国产出新闻解释力弱。</li><li>拉力是脆弱性清单：外债币种与期限、储备、制度决定同一阵风下谁倒。</li><li>骤停是状态切换，经币种错配放大；浮动不绝缘，需要干预与管制两个第二工具。</li><li>出处：Calvo, <em>Journal of Applied Economics</em> 1998；Forbes–Warnock, <em>JIE</em> 2012；Rey 2013；Obstfeld 2012。</li></ul>',5))])}const S=t(p,[["render",C]]);export{u as __pageData,S as default};
